import json, sys
import categorizationapp
from categorizationapp import app

def run(bank, txns, acc_type="SAVING", holder="RAHUL SHARMA", pfm=False):
    payload = {
        "bank": bank,
        "acc_type": acc_type,
        "accountUID": "acc-1",
        "accountHolder": holder,
        "isPFMEnabled": pfm,
        "transactions": txns,
    }
    with app.test_client() as c:
        r = c.post("/categorizeTransaction", json=payload)
        return r.get_json()

def txn(desc, amount, ttype, remark="", bal=10000.0, date="2022-01-01"):
    return {
        "description": desc,
        "amount": amount,
        "type": ttype,
        "remark": remark,
        "balanceAfterTransaction": bal,
        "transactionDate": date,
        "valueDate": date,
    }

def show(bank, txns, **kw):
    res = run(bank, txns, **kw)
    if "response" not in res:
        print(bank, "ERROR", res)
        return
    print(f"=== {bank} ===")
    for t in res["response"]:
        print(f"  desc={t['description']!r} remark={t.get('remark')!r} amt={t['amount']} {t['type']}")
        print(f"     cat={t.get('transactionCategory')!r} sub={t.get('transactionSubcategory')!r} party={t.get('partyName')!r} merch={t.get('merchantType')!r}")

if __name__ == "__main__":
    pass

